void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting) {
    ktime_t expires;

    if (timr->it_interval.tv64 != 0) {
        /* It's an interval timer */
        cur_setting->it_interval = timr->it_interval;
    } else {
        /* It's a oneshot timer */
        expires = timr->it_expire;
        if (expires.tv64 == 0) {
            /* Timer is expired and is a oneshot timer with no signal */
            cur_setting->it_interval.tv64 = 0;
            cur_setting->it_value.tv64 = 0;
        } else {
            /* Calculate remaining time until timer expires */
            struct timespec64 now;
            ktime_get_coarse_real_ts64(&now);
            cur_setting->it_value.tv64 = expires.tv64 - now.tv64;
        }
    }
}

void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting) {
    ktime_t now, expires;

    now = ktime_get();

    if (timr->it_interval.tv64 != 0) {
        cur_setting->it_interval = timr->it_interval;
    } else {
        cur_setting->it_interval.tv64 = 0;
    }

    expires = ktime_add(timr->it_expire, timr->it_interval);
    if (ktime_after_eq(now, timr->it_expire) && !timr->is_signal) {
        cur_setting->it_value.tv64 = 0;
    } else {
        cur_setting->it_value = ktime_sub(expires, now);
    }
}

void get_timer_settings(struct k_itimer *timer, struct itimerspec64 *cur_setting) {
    ktime_t now;
    s64 remaining_nsec;

    now = ktime_get();

    if (timer->it_interval.tv64 != 0) {
        cur_setting->it_interval = timer->it_interval;
    } else {
        cur_setting->it_interval.tv64 = 0;
    }

    if (timer->it_overrun == 0 && timer->it_sigev_notify == SIGEV_NONE) {
        remaining_nsec = ktime_to_ns(ktime_sub(timer->it_expire, now));
        if (remaining_nsec <= 0) {
            cur_setting->it_value.tv64 = 0;
        } else {
            cur_setting->it_value.tv64 = remaining_nsec;
        }
    } else {
        cur_setting->it_value.tv64 = 0;
    }
}

void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting)
{
    ktime_t now = ktime_get();
    ktime_t expires = timr->it_real.function;

    if (expires.tv64 == 0) {
        cur_setting->it_interval.tv64 = 0;
        cur_setting->it_value.tv64 = 0;
    } else {
        if (expires.tv64 <= now) {
            cur_setting->it_interval.tv64 = 0;
            cur_setting->it_value.tv64 = 0;
        } else {
            cur_setting->it_interval = timr->it_interval;
            cur_setting->it_value = ktime_sub(expires, now);
        }
    }
}

void get_timer_settings(struct k_itimer *timr, struct itimerspec64 *cur_setting) {
    ktime_t expires;
    s64 iv, rem;

    if (timr->it_interval.tv64) {
        cur_setting->it_interval = timr->it_interval;
    } else {
        cur_setting->it_interval.tv64 = 0;
    }

    expires = timr->it_expires;

    if (expires == 0) {
        cur_setting->it_value.tv64 = 0;
        return;
    }

    iv = ktime_get_raw();
    rem = ktime_to_ns(ktime_sub(expires, iv));

    if (rem <= 0) {
        cur_setting->it_value.tv64 = 0;
    } else {
        cur_setting->it_value.tv64 = rem;
    }
}
